package dev.veltraph.client.navigation;
import dev.veltraph.client.world.Vec3;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class GroundDropBrakeForecastTest {
    private static final Vec3 ORIGIN=new Vec3(.5,71,3.5),TARGET=new Vec3(.5,70,4.5),ACTUAL=new Vec3(.5,70.76636799395752,4.67543971796843),VELOCITY=new Vec3(0,-.230527368912964,.10725115763215755);
    private static GroundDropBrakeForecast.Episode begin(){return GroundDropBrakeForecast.begin(100,false,ACTUAL,VELOCITY,ORIGIN,TARGET,.1).orElseThrow();}
    @Test void actualCore12FailsOnlyOldForwardProjectionWhileCurrentCapsHold(){assertTrue(GroundLocomotionMotion.dropCurrent(ACTUAL,VELOCITY,ORIGIN,TARGET,.1));assertFalse(GroundLocomotionMotion.drop(ACTUAL,VELOCITY,ORIGIN,TARGET,.1));assertEquals(4.889942033232745,ACTUAL.z()+2*VELOCITY.z(),1e-12);assertTrue(ACTUAL.z()+2*VELOCITY.z()>TARGET.z()+.35);}
    @Test void neutralFallForecastIsFiniteAndRequiresOriginalLandingCellAndTolerance(){var e=begin();assertEquals(2,e.gravityStage());assertEquals(3,e.remaining().size());assertTrue(e.landing().z()>TARGET.z()+.35);assertTrue(e.landing().distanceTo(TARGET)<.65);assertEquals(GroundPathfinder.node(TARGET),GroundPathfinder.node(e.landing()));assertEquals(70,e.landing().y());assertTrue(e.coast().z()>e.landing().z());assertFalse(e.nextGround());}
    @Test void onlyPublishedNeutralSuccessiveNativeSamplesCanContinueEpisode(){var e=begin();var first=e.remaining().getFirst();var next=GroundDropBrakeForecast.resume(e,101,e.nextGround(),first,e.nextVelocity(),ORIGIN,TARGET,.1).orElseThrow();assertEquals(3,next.gravityStage());assertTrue(GroundDropBrakeForecast.resume(e,102,e.nextGround(),first,e.nextVelocity(),ORIGIN,TARGET,.1).isEmpty());assertTrue(GroundDropBrakeForecast.resume(e,101,true,first,e.nextVelocity(),ORIGIN,TARGET,.1).isEmpty());}
    @Test void mismatchedPositionVelocitySpeedAndTargetDeny(){var e=begin();var first=e.remaining().getFirst();assertTrue(GroundDropBrakeForecast.resume(e,101,false,new Vec3(first.x(),first.y(),first.z()+.01),e.nextVelocity(),ORIGIN,TARGET,.1).isEmpty());assertTrue(GroundDropBrakeForecast.resume(e,101,false,first,new Vec3(.3,e.nextVelocity().y(),e.nextVelocity().z()),ORIGIN,TARGET,.1).isEmpty());assertTrue(GroundDropBrakeForecast.resume(e,101,false,first,e.nextVelocity(),ORIGIN,TARGET,.2).isEmpty());assertTrue(GroundDropBrakeForecast.resume(e,101,false,first,e.nextVelocity(),ORIGIN,new Vec3(.5,70,4.6),.1).isEmpty());}
    @Test void actualNativeLandingFlagIsRequiredAtPredictedCollision(){var e=begin();while(!e.nextGround())e=GroundDropBrakeForecast.resume(e,e.tick()+1,false,e.remaining().getFirst(),e.nextVelocity(),ORIGIN,TARGET,.1).orElseThrow();assertTrue(GroundDropBrakeForecast.resume(e,e.tick()+1,false,e.remaining().getFirst(),e.nextVelocity(),ORIGIN,TARGET,.1).isEmpty());var landed=GroundDropBrakeForecast.resume(e,e.tick()+1,true,e.remaining().getFirst(),e.nextVelocity(),ORIGIN,TARGET,.1).orElseThrow();assertTrue(landed.remaining().isEmpty());assertEquals(70,landed.actual().y());}
    @Test void foreignFallOrUnsupportedOldCurrentRectangleCannotAnchor(){assertTrue(GroundDropBrakeForecast.begin(100,true,ACTUAL,VELOCITY,ORIGIN,TARGET,.1).isEmpty());assertTrue(GroundDropBrakeForecast.begin(100,false,ACTUAL,new Vec3(0,-.4,VELOCITY.z()),ORIGIN,TARGET,.1).isEmpty());assertTrue(GroundDropBrakeForecast.begin(100,false,new Vec3(.5,ACTUAL.y(),4.9),VELOCITY,ORIGIN,TARGET,.1).isEmpty());}
}
